// Builds slides/GroupP1-9.pptx. Load/stress/accuracy numbers are read from
// step5/results (generated by analyse_jtl.py and accuracy_test.py), so the deck
// reconciles with the logs.
// Run from the repo root:  node slides/build_deck.js   (needs pptxgenjs on NODE_PATH)
const fs = require("fs");
const path = require("path");
const pptxgen = require("pptxgenjs");

const ROOT = path.resolve(__dirname, "..");
const R = (p) => path.join(ROOT, p);
const OUT = R("slides/GroupP1-9.pptx");
const APPLY_THEME = process.env.APPLY_THEME; // path to the pptx skill's apply_theme.js (optional)

// ---------- data ----------
function readCsv(p) {
  const [head, ...lines] = fs.readFileSync(R(p), "utf8").trim().split(/\r?\n/);
  const cols = head.split(",");
  return lines.map((l) => Object.fromEntries(l.split(",").map((v, i) => [cols[i], v])));
}
const levels = readCsv("step5/results/levels.csv");
const lvl = (model, level, ep) => levels.find((r) => r.model === model && r.level === level && r.endpoint === ep);
const acc = Object.fromEntries(
  ["gemma3-1b", "qwen3-4b", "llama3.1-8b"].map((m) => [m, JSON.parse(fs.readFileSync(R(`step5/results/${m}/accuracy/summary.json`), "utf8"))])
);
const timeline = readCsv("step5/results/qwen3-4b/stress_60-1200ph_40min/run1/timeline.csv");
const hist = readCsv("workload/ticket_lengths_hist.csv").filter((r) => +r.tickets > 0);

const MODELS = [
  { key: "gemma3-1b", name: "Gemma 3 1B", color: "8E9AA3" },
  { key: "qwen3-4b", name: "Qwen3 4B", color: "2A9D8F" },
  { key: "llama3.1-8b", name: "Llama 3.1 8B", color: "E07A1F" },
];
const CATS = ["Credit reporting", "Debt collection", "Mortgage", "Credit card", "Bank account or service", "Consumer loan", "Money transfer or service"];
const s = (ms, d = 1) => (+ms / 1000).toFixed(d);

// ---------- theme ----------
const THEME = {
  name: "Triage Teal",
  headFontFace: "Cambria",
  bodyFontFace: "Calibri",
  colors: {
    dk1: "1B2A30", lt1: "FFFFFF", dk2: "12343B", lt2: "EEF3F4",
    accent1: "2A9D8F", accent2: "E07A1F", accent3: "8E9AA3", accent4: "C0392B",
    accent5: "3D6B73", accent6: "F2C14E", hlink: "1F6F8B", folHlink: "5B4B8A",
  },
};
const HEX = THEME.colors;
const PASS = "2A9D8F", FAIL = "C0392B", WARN = "E07A1F";

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9"; // 10 x 5.625 in
pres.theme = { headFontFace: THEME.headFontFace, bodyFontFace: THEME.bodyFontFace };
pres.title = "Group P1-9 ICT3113 Assignment 1";
pres.author = "Group P1-9";
const C = pres.SchemeColor;

pres.defineSlideMaster({
  title: "DARK",
  background: { color: HEX.dk2 },
  objects: [],
});
pres.defineSlideMaster({
  title: "CONTENT",
  background: { color: HEX.lt1 },
  margin: [0.4, 0.5, 0.4, 0.5],
  objects: [
    { placeholder: { options: { name: "title", type: "title", x: 0.5, y: 0.25, w: 9.0, h: 0.6, fontSize: 22, bold: true, color: C.text2, fontFace: THEME.headFontFace, valign: "middle", align: "left", margin: 0 }, text: "" } },
    { text: { text: "Group P1-9 · ICT3113 Assignment 1", options: { x: 0.5, y: 5.3, w: 5, h: 0.25, fontSize: 9, color: C.accent3, margin: 0 } } },
  ],
  slideNumber: { x: 9.0, y: 5.3, w: 0.5, h: 0.25, fontSize: 9, color: HEX.accent3, align: "right" },
});

// ---------- helpers ----------
const txt = (slide, text, o) => slide.addText(text, { isTextBox: true, margin: 0, fontSize: 12, color: C.text1, valign: "top", ...o });
function card(slide, x, y, w, h, fill = HEX.lt2) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x, y, w, h, fill: { color: fill }, line: { color: fill }, rectRadius: 0.08 });
}
function stat(slide, x, y, w, big, label, color = C.text2) {
  txt(slide, big, { x, y, w, h: 0.5, fontSize: 26, bold: true, color, fontFace: THEME.headFontFace });
  txt(slide, label, { x, y: y + 0.5, w, h: 0.45, fontSize: 10, color: C.text1 });
}
const hdr = (t) => ({ text: t, options: { bold: true, color: "FFFFFF", fill: { color: HEX.dk2 } } });
const cell = (t, o = {}) => ({ text: String(t), options: o });
function verdict(v) {
  const color = v.startsWith("PASS") ? PASS : v.startsWith("FAIL") ? FAIL : WARN;
  return cell(v, { bold: true, color: "FFFFFF", fill: { color }, align: "center" });
}
function contentSlide(title, section) {
  const sl = pres.addSlide({ masterName: "CONTENT", sectionTitle: section });
  sl.addText(title, { placeholder: "title", fontSize: 22, align: "left" });
  return sl;
}

