// ================= 8 Playbook =================
{
  const sl = contentSlide("Playbook: freeze, deploy, measure, reconcile", "Testing");
  const steps = [
    ["1 Freeze", "Golden set + predictions committed (3567f80) before any model run"],
    ["2 Deploy", "switch_model.ps1: save logs, set tag, 2 synthetic warm-ups, TRUNCATE, check /stats = 0"],
    ["3 Accuracy", "160 golden tickets, one at a time, via POST /tickets; non-201 = wrong + non-conformant"],
    ["4 Load", "Redeploy (empty DB); 3 levels × 3 runs from the load-generator PC"],
    ["5 Stress", "Qwen3 4B: POST ramp 60 → 1,200/h over 40 min; search fixed at 316/h"],
    ["6 Reconcile", "save_logs.ps1 → analyse_jtl.py: every JMeter sample ↔ log line by request ID; /stats delta"],
  ];
  steps.forEach(([h, b], i) => {
    const x = 0.5 + (i % 3) * 3.05, y = 0.95 + Math.floor(i / 3) * 1.25;
    card(sl, x, y, 2.85, 1.1, i === 4 ? "FBEBDD" : "DDF0EE");
    txt(sl, [{ text: h, options: { bold: true, color: HEX.dk2, fontSize: 13, breakLine: true } }, { text: b }], { x: x + 0.12, y: y + 0.08, w: 2.62, h: 0.96, fontSize: 10.5 });
  });
  card(sl, 0.5, 3.55, 9.0, 1.6, "F4F6F7");
  txt(sl, "Open-loop JMeter configuration (step5/jmeter/ticket_triage.jmx)", { x: 0.65, y: 3.62, w: 8.7, h: 0.28, fontSize: 12, bold: true, color: C.text2 });
  txt(sl, [
    { text: "Two Open Model Thread Groups (POST, search). Schedule: rate(R/hour) random_arrivals(22 min) pause(1 min), so arrivals never wait for responses.", options: { bullet: { indent: 12 }, breakLine: true } },
    { text: "First 2 min = warm-up, excluded; 20-min measurement window; arrival seeds 1, 2, 3; 60 s cooldown between runs.", options: { bullet: { indent: 12 }, breakLine: true } },
    { text: "Data: 840 non-golden team rows (9000–9839) as JSON bodies; 20 search terms. Timeouts: connect 10 s, response 310 s.", options: { bullet: { indent: 12 }, breakLine: true } },
    { text: "Each request has X-Request-ID = UUID, saved in the .jtl and in the API log. Full procedure: step5/README.md.", options: { bullet: { indent: 12 } } },
  ], { x: 0.65, y: 3.92, w: 8.7, h: 1.2, fontSize: 10.5, paraSpaceAfter: 2 });
  sl.addNotes("Metric definitions (analyse_jtl.py): window = [t0 + warm-up, t0 + warm-up + 20 min) by request start time; p50/p95/p99 = nearest-rank over all samples in the window, failures included; achieved/h = successful requests completing inside the window; error % = JMeter success=false. Each run reuses the same ticket order, so content is controlled and only arrival timing varies between runs.");
}

// ================= 9 Load & stress =================
pres.addSection({ title: "Results" });
{
  const sl = contentSlide("Load and stress: Ollama inference is the bottleneck", "Results");
  const rows = [[hdr("Model"), hdr("POST/h"), hdr("p50 s"), hdr("p95 s [min–max]"), hdr("p99 s"), hdr("Done/h"), hdr("Err %")]];
  const lvlName = { average: "43", peak: "81", headroom: "105" };
  MODELS.forEach((m) => ["average", "peak", "headroom"].forEach((lv, j) => {
    const r = lvl(m.key, lv, "POST /tickets");
    const p95 = `${s(r.p95_ms_mean)} [${s(r.p95_ms_min)}–${s(r.p95_ms_max)}]`;
    const bad95 = +r.p95_ms_mean > 30000, badErr = +r.error_pct_mean > 1;
    rows.push([
      cell(j === 0 ? m.name : "", { bold: true, color: m.color }), cell(lvlName[lv], lv === "headroom" ? { bold: true } : {}), cell(s(r.p50_ms_mean)),
      cell(p95, bad95 ? { bold: true, color: FAIL } : {}), cell(s(r.p99_ms_mean)), cell(Math.round(+r.achieved_per_h_mean)),
      cell((+r.error_pct_mean).toFixed(1) + (m.key === "llama3.1-8b" && lv === "headroom" ? "*" : ""), badErr ? { bold: true, color: FAIL } : {}),
    ]);
  }));
  sl.addTable(rows, { x: 0.5, y: 0.95, w: 5.15, colW: [1.05, 0.6, 0.55, 1.25, 0.55, 0.6, 0.55], fontSize: 9.5, border: { type: "solid", color: "D5DEE1", pt: 0.5 }, margin: 0.03, rowH: 0.24, valign: "middle" });
  txt(sl, "Mean of 3 runs (open-loop, 20-min windows). GET /search p95 ≤ 0.38 s in all 27 runs; 0 search errors. *Llama: 2 JMeter test-end aborts; server returned 201 for both.", { x: 0.5, y: 3.45, w: 5.15, h: 0.5, fontSize: 9, italic: true, color: C.accent5 });
  const mins = timeline.map((t) => t.minute);
  sl.addChart(pres.charts.LINE, [
    { name: "Offered/min", labels: mins, values: timeline.map((t) => +t.post_arrivals) },
    { name: "Completed OK/min", labels: mins, values: timeline.map((t) => +t.post_completed_ok) },
    { name: "Backlog", labels: mins, values: timeline.map((t) => +t.approx_backlog) },
  ], {
    x: 5.85, y: 0.9, w: 3.65, h: 2.75, chartColors: [HEX.accent3, HEX.accent1, HEX.accent4], lineSize: 1.5, lineDataSymbol: "none",
    showTitle: true, title: "Qwen3 4B stress ramp: POST per minute", titleFontSize: 10, titleColor: HEX.dk2, titleFontFace: "+mn-lt",
    showLegend: true, legendPos: "b", legendFontSize: 8, legendFontFace: "+mn-lt", catAxisLabelFontSize: 8, valAxisLabelFontSize: 8, catAxisLabelFontFace: "+mn-lt", valAxisLabelFontFace: "+mn-lt",
    catAxisLabelColor: "5A6A70", valAxisLabelColor: "5A6A70", valGridLine: { color: "E1E7EA", size: 0.5 }, catGridLine: { style: "none" }, catAxisLabelFrequency: 5,
    catAxisTitle: "minute", showCatAxisTitle: true, catAxisTitleFontSize: 8, catAxisTitleColor: "5A6A70",
  });
  txt(sl, [
    { text: "Limit found: ~470–480 tickets/h. ", options: { bold: true } },
    { text: "Up to 450/h offered it keeps up (backlog ≤ 3). From minute 21 (~600/h offered) the backlog rises every minute, latency grows 52 s → 280 s, and from minute 30 requests fail with 502 at the 300 s timeout. Search p95 stays 0.13 s." },
  ], { x: 5.85, y: 3.7, w: 3.65, h: 1.5, fontSize: 10 });
  txt(sl, [
    { text: "Diagnosis: ", options: { bold: true } },
    { text: "NUM_PARALLEL = 1, so tickets queue behind the model; nothing else saturates. Gemma has spare capacity but rejects 16.5% of tickets. Llama (13 s per ticket) has no burst margin: random clusters gave p95 from 18 s to 90 s across runs at 105/h." },
  ], { x: 0.5, y: 3.98, w: 5.15, h: 1.2, fontSize: 10 });
  sl.addNotes("Source: step5/results/levels.csv, runs.csv, summary.md and the stress timeline.csv. Llama headroom per run: p95 18.2 s / 34.7 s / 89.7 s; run 3 had 5 arrivals within ~1.2 min. Reconciliation: 3,640 JMeter samples across 28 runs, every one matched to a service-log line; 73 status mismatches, all JMeter test-end aborts (71 in the stress run, 2 in Llama headroom run 3), where the server log shows the real outcome.");
}

